import{_ as r}from"./chunks/SIMD-Reg矢量计算内存层级.hDa4pNmE.js";import{c as t,Q as o,j as l,m as a}from"./chunks/framework.DOi4mjdC.js";const C=JSON.parse('{"title":"AI Core SIMD编程模型概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"AI Core SIMD编程模型概述","slug":"ai-core-simd编程模型概述"},{"level":2,"title":"引言","slug":"引言"},{"level":2,"title":"异构并行计算核心模型：SPMD嵌套SIMD编程范式","slug":"异构并行计算核心模型spmd嵌套simd编程范式"},{"level":2,"title":"硬件底层支撑：AI Core计算单元架构与算子分类","slug":"硬件底层支撑ai-core计算单元架构与算子分类"},{"level":3,"title":"AI Core核心硬件组件","slug":"ai-core核心硬件组件"},{"level":3,"title":"基于硬件单元的三类标准算子","slug":"基于硬件单元的三类标准算子"},{"level":2,"title":"基于AI Core的SIMD算子开发通用步骤","slug":"基于ai-core的simd算子开发通用步骤"},{"level":3,"title":"算子Kernel通用开发四步法","slug":"算子kernel通用开发四步法"},{"level":3,"title":"新架构双模式矢量计算结构","slug":"新架构双模式矢量计算结构"},{"level":2,"title":"多级编程接口体系：分层抽象与能力差异","slug":"多级编程接口体系分层抽象与能力差异"},{"level":3,"title":"算子多级编程接口发展回顾","slug":"算子多级编程接口发展回顾"},{"level":3,"title":"Ascend C多级编程接口","slug":"ascend-c多级编程接口"},{"level":2,"title":"小结","slug":"小结"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/概述.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMD编程/概述.md"}'),n={name:"guide/编程指南/编程模型/AI-Core-SIMD编程/概述.md"};function s(i,e,g,h,d,c){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="ai-core-simd编程模型概述" tabindex="-1">AI Core SIMD编程模型概述 <a class="header-anchor" href="#ai-core-simd编程模型概述" aria-label="Permalink to &quot;AI Core SIMD编程模型概述&quot;">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>SIMD并行机制是AI Core的核心算力支撑，承担了整机90%以上的计算吞吐量。因此，本章将以<strong>SIMD编程模型</strong>为核心主线，遵循「宏观架构—硬件调度—代码落地」的递进逻辑，完整覆盖SIMD算子开发全链路：阐述多AI Core集群的并行任务分发机制，拆解单AI Core内部异构计算单元的任务调度逻辑，并逐层讲解如何基于差异化的C/C++编程接口，完成<a href="./核函数.html">算子Kernel</a>计算逻辑的开发。</p><h2 id="异构并行计算核心模型-spmd嵌套simd编程范式" tabindex="-1">异构并行计算核心模型：SPMD嵌套SIMD编程范式 <a class="header-anchor" href="#异构并行计算核心模型-spmd嵌套simd编程范式" aria-label="Permalink to &quot;异构并行计算核心模型：SPMD嵌套SIMD编程范式&quot;">​</a></h2><p>昇腾NPU异构并行体系采用<strong>外层多核SPMD（Single Program Multiple Data）并行 + 内层单核SIMD细粒度并行</strong>的双层融合架构，是AI Core算子开发的核心理论根基。所有SIMD算子的并行逻辑、数据拆分策略、任务调度机制，均基于该编程范式实现。</p><p><strong>多核集群层面遵循SPMD编程模型</strong>：将每个AI Core抽象成一个Block，通过内置变量<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">block_idx</a> 作为Block索引。每个Block执行同一份算子Kernel代码，一般基于<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">block_idx</a>划分每个Block的数据处理范围，实现多核负载均衡与并行调度。</p><p><strong>单核计算层面依托SIMD并行机制</strong>：单个AI Core内部基于<a href="./../编程模型概述.html">SIMD</a>机制实现细粒度并行，依靠硬件专用计算单元，单条指令批量完成多组同质数据的并行运算，充分挖掘单AI Core的极致算力潜力。</p><h2 id="硬件底层支撑-ai-core计算单元架构与算子分类" tabindex="-1">硬件底层支撑：AI Core计算单元架构与算子分类 <a class="header-anchor" href="#硬件底层支撑-ai-core计算单元架构与算子分类" aria-label="Permalink to &quot;硬件底层支撑：AI Core计算单元架构与算子分类&quot;">​</a></h2><p>AI Core是昇腾NPU的基础核心计算单元，采用「控制单元+异构计算单元+分级本地存储」的经典架构，各组件分工明确、协同联动。硬件的能力边界直接决定算子的计算形态与开发方式，下文将详细介绍AI Core核心硬件组件，以及基于硬件能力划分的标准化算子类型。</p><h3 id="ai-core核心硬件组件" tabindex="-1">AI Core核心硬件组件 <a class="header-anchor" href="#ai-core核心硬件组件" aria-label="Permalink to &quot;AI Core核心硬件组件&quot;">​</a></h3><ul><li><strong>标量处理单元</strong>：作为AI Core的控制中枢，主要负责地址偏移计算、指令调度与发射，统筹管控其他运算单元的指令执行流程，支撑分支、循环等各类控制流逻辑的正常运行。</li><li><strong>向量处理单元<a href="./../../高级编程/硬件实现/基本架构.html">Vector</a></strong>：遵循标准SIMD并行计算逻辑，专职执行各类向量指令，支持单指令多数据并行运算，适配元素级计算、逻辑运算、数据重组等灵活性要求高的计算场景。</li><li><strong>矩阵运算单元<a href="./../../高级编程/硬件实现/基本架构.html">Cube</a></strong>：高密度张量专用算力单元，面向矩阵乘加、高维张量卷积等算力密集型场景深度优化。硬件原生支持批量矩阵运算，典型能力为单次完成一组float16类型16×16矩阵乘法，是AI模型训练与推理场景的核心算力支撑。</li><li><strong>本地存储</strong>：AI Core片内高速存储体系，用于缓存计算中间数据，规避频繁访问低速全局内存的性能损耗，降低访存延迟。其中Cube计算单元配套<a href="./../../高级编程/硬件实现/基本架构.html">L1 Buffer</a>、<a href="./../../高级编程/硬件实现/基本架构.html">L0C Buffer</a> 等；Vector计算单元配套统一缓存<a href="./../../高级编程/硬件实现/基本架构.html">UB（Unified Buffer）</a>；Ascend 950PR/Ascend 950DT的AI Core向量单元新增可编程向量寄存器（Register），单寄存器大小为256B。</li></ul><h3 id="基于硬件单元的三类标准算子" tabindex="-1">基于硬件单元的三类标准算子 <a class="header-anchor" href="#基于硬件单元的三类标准算子" aria-label="Permalink to &quot;基于硬件单元的三类标准算子&quot;">​</a></h3><p>根据算子核心计算逻辑对硬件单元的依赖差异，AI Core算子可划分为三大标准类型，通过专属修饰符标准化硬件资源调度规则，统一全域算子开发规范：</p><ul><li><strong>矢量类算子</strong>：核心计算逻辑完全由Vector计算单元承载，无矩阵密集运算，以元素级、逻辑类、数据重组类计算为主，适配访存密集、灵活度要求高的场景。核函数通过<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">__vector__</a>修饰。</li><li><strong>矩阵类算子</strong>：核心计算逻辑完全由Cube计算单元承载，以大维度矩阵乘、张量卷积等规整算力密集计算为主，追求极致硬件吞吐，核函数通过 <a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">__cube__</a>修饰。</li><li><strong>融合类算子</strong>：工业界主流复杂算子形态，可联动调度Cube计算单元与Vector计算单元协同计算，兼顾矩阵高密度算力运算与向量灵活逻辑处理，核函数通过<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">__mix__(cube, vec)</a> 修饰，其中__mix__(cube, vec)表示启动的 Cube 核与 Vector 核的配比，支持的配比包括 (1, 0)、(0, 1)、(1, 1)、(1, 2)。</li></ul><blockquote><p>📌 <strong>提示</strong>：NPU硬件架构可分为<a href="./../../高级编程/硬件实现/基本架构.html">分离模式</a> 和 <a href="./../../高级编程/硬件实现/基本架构.html">耦合模式</a> 。分离模式下，两类计算单元各自配备独立标量控制单元；耦合模式下，Cube与Vector单元共享同一个标量控制单元。其中__mix__修饰符仅在分离模式下生效，耦合模式硬件不支持该特性。更详尽的硬件架构信息请参见 <a href="./../../高级编程/硬件实现/基本架构.html">硬件实现</a>章节。</p></blockquote><h2 id="基于ai-core的simd算子开发通用步骤" tabindex="-1">基于AI Core的SIMD算子开发通用步骤 <a class="header-anchor" href="#基于ai-core的simd算子开发通用步骤" aria-label="Permalink to &quot;基于AI Core的SIMD算子开发通用步骤&quot;">​</a></h2><p>基于SPMD+SIMD双层编程模型，所有AI Core核运行同一份Kernel核函数，通过 <strong><a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">block_idx</a></strong> 区分数据分片，实现多核并行计算。因此，算子开发的首要步骤为 <strong>Tiling（分块）设计</strong>：对全局超大张量数据做均匀切分，为每个AI Core分配独立数据块，保障多核负载均衡。</p><p>此外，与传统CPU串行编程、<a href="./../编程模型概述.html">SIMT</a> 线程编程不同，AI Core SIMD编程的显著特征是<strong>显式分层访存</strong>：开发者需手动管控数据流转，将数据从Global Memory（全局内存，又称Device Memory，简称GM）搬运至AI Core片内Local Memory（本地内存，典型包含L1 Buffer、UB）完成计算，最终将运算结果写回全局内存。</p><h3 id="算子kernel通用开发四步法" tabindex="-1">算子Kernel通用开发四步法 <a class="header-anchor" href="#算子kernel通用开发四步法" aria-label="Permalink to &quot;算子Kernel通用开发四步法&quot;">​</a></h3><p>基于SIMD的AI Core算子开发一般包含四个主要步骤，适配绝大多数算子开发场景：</p><ol><li><strong>Tiling（分块）设计</strong>：对全局超大张量数据进行均匀切分，为各AI Core分配大小均衡的独立数据分片，精准适配SPMD多核并行架构，规避单核算力瓶颈，实现全域负载均衡。</li><li><strong>数据搬入</strong>：调用SIMD编程接口，将全局内存中的待计算数据，批量搬运至L1 Buffer、UB等AI Core片内高速本地内存。</li><li><strong>数据计算</strong>：根据算子类型调度Cube计算单元或Vector计算单元，依托片内高速缓存数据，完成矩阵、向量或混合逻辑计算；针对同一计算任务，后续章节将介绍多级差异化编程接口，可分别适配开发效率、极致性能、C/C++编程习惯等不同开发诉求。</li><li><strong>数据搬出</strong>：计算完成后，将片内存储中的结果数据写回全局内存，完成单次算子计算流程。</li></ol><blockquote><p>📌 <strong>提示</strong>：AI Core片内本地存储空间有限，无法一次性加载超大尺寸张量。实际开发中普遍采用「迭代分块搬运、分批计算、结果累加」的策略完成全域数据计算，同时搭配流水线技术屏蔽数据搬运耗时，提升整体运算效率。</p></blockquote><h3 id="新架构双模式矢量计算结构" tabindex="-1">新架构双模式矢量计算结构 <a class="header-anchor" href="#新架构双模式矢量计算结构" aria-label="Permalink to &quot;新架构双模式矢量计算结构&quot;">​</a></h3><p>Ascend 950PR/Ascend 950DT新一代架构在传统UB缓存体系的基础上，开放寄存器（Register）可编程能力，构建出「Global Memory → UB → Register」的三级内存层级，衍生出两套适配不同性能诉求的矢量计算模式，实现通用场景与极致性能场景的全覆盖。其内存层级结构如下图所示：</p><p><strong>图 1</strong> SIMD Reg矢量计算内存层级<br><img src="'+r+'" alt="" title="SIMD-Reg矢量计算内存层级"></p><p>基于全新三级内存架构，矢量计算分为通用的<strong>Memory矢量计算</strong>与高性能的<strong>Reg矢量计算</strong>：</p><ul><li><p><strong>Memory 矢量计算（传统通用模式）</strong>：具备全架构兼容、流程简洁稳定、通用性强的特点，全程基于UB完成数据缓存与运算。</p><ul><li>数据搬入：Global Memory → UB</li><li>矢量计算：基于 <strong>UB</strong> 完成矢量计算</li><li>数据搬出：UB → Global Memory</li></ul></li><li><p><strong>Reg 矢量计算（高性能模式）</strong>：依托寄存器低延迟、高带宽的硬件优势，专为极致性能优化场景设计：</p><ul><li>数据搬入：全局内存 → UB → 寄存器（<strong>Reg</strong>）</li><li>矢量计算：基于 <strong>Reg</strong> 完成矢量计算</li><li>数据搬出：寄存器（<strong>Reg</strong>） → UB → 全局内存</li></ul></li></ul><p>向量寄存器位于Vector计算单元的最内层，拥有最低访存延迟与最高带宽，开放寄存器可编程能力，有助于开发者充分释放硬件峰值计算性能。</p><h2 id="多级编程接口体系-分层抽象与能力差异" tabindex="-1">多级编程接口体系：分层抽象与能力差异 <a class="header-anchor" href="#多级编程接口体系-分层抽象与能力差异" aria-label="Permalink to &quot;多级编程接口体系：分层抽象与能力差异&quot;">​</a></h2><h3 id="算子多级编程接口发展回顾" tabindex="-1">算子多级编程接口发展回顾 <a class="header-anchor" href="#算子多级编程接口发展回顾" aria-label="Permalink to &quot;算子多级编程接口发展回顾&quot;">​</a></h3><p>早期算子开发以C语言裸指针编程为核心，依托C语言底层内存操控能力，可直接通过指针寻址、操作设备内存，同时配套与硬件底层指令精准映射的原生接口，支持向量计算、矩阵乘、数据搬运等硬件原语调用。该模式可实现硬件缓存、寄存器等资源的精细化管控，是底层极致性能优化的核心方案，广泛应用于离散类、归约类、矩阵类等核心算子的底层实现。</p><p>随着深度学习持续迭代演进，AI计算核心载体升级为4D/5D高维张量（如NLP模型注意力张量、CV模型特征图张量）。传统裸指针编程需手动完成内存偏移计算、维度拆分、边界校验等重复性工作，不仅开发效率低下，还易引发内存越界、索引错误等稳定性问题。</p><p>在此背景下，基于C++面向对象特性的Tensor抽象应运而生。Tensor内置内存布局（Layout）、数据类型等张量元信息，其中Layout包含维度（Shape）、步长（Stride）等，可简化内存布局的管理，降低高维张量开发成本。业界由此逐步形成主流的Tensor/Tile编程模型：核心思想是将全局张量（Tensor）切分为规则且固定尺寸的数据分块（Tile），以Tile作为计算、存储与硬件调度的最小单元。其中，Tensor是多维数组的标准化数学与计算抽象，是AI场景下向量、矩阵、高维特征图等各类数据的统一表示形式，仅描述全局逻辑结构，不绑定硬件执行细节；Tile则是AI加速芯片张量核心、矢量核心的最小调度、计算与数据搬运粒度，作为编程模型的物理层载体，承担着衔接全局数据与底层硬件的作用。通过将全局Tensor切分为适配硬件存储与算力规格的Tile，结合数据搬运、流水线调度、片上内存复用等优化手段，可充分挖掘并释放硬件极限算力。</p><p>当前Tensor/Tile编程范式主要包含两类实现路径：手工Tensor/Tile编程一般基于C/C++实现，由开发者全权管控内存布局、分块策略、数据搬运与流水线调度全流程；自动化Tensor/Tile编程一般基于Python DSL（领域专用语言）实现，如<a href="https://gitcode.com/cann/pypto" target="_blank" rel="noreferrer">PyPTO</a> 、<a href="https://github.com/tile-ai/tilelang-ascend" target="_blank" rel="noreferrer">TileLang</a>、<a href="https://github.com/openai/triton" target="_blank" rel="noreferrer">Triton</a>等领域专用语言，由AI编译器自动完成内存分配、资源复用、任务调度与依赖同步，降低开发门槛。</p><h3 id="ascend-c多级编程接口" tabindex="-1">Ascend C多级编程接口 <a class="header-anchor" href="#ascend-c多级编程接口" aria-label="Permalink to &quot;Ascend C多级编程接口&quot;">​</a></h3><p>Ascend C秉持「标准C/C++语法、最小化扩展」的核心设计原则，打造轻量化、高性能的底层编程基座，为昇腾系列芯片提供极致性能导向的算子开发能力。同时精准适配C、C++开发者的差异化编程习惯，实现底层硬件精细化管控与上层工程化高效开发的最优平衡。</p><p>基于上述设计理念与业界通用开发实践，Ascend C原生提供两套核心编程体系：面向指针编程的C语言接口、面向Tensor编程的C++类库基础API。此外，Ascend C借鉴经典C/C++队列管道（Queue Pipeline）设计思想，创新性推出TPipe/TQue编程框架，简化异构计算场景下的内存调度、数据同步与流水线管控复杂度，有效降低了高性能算子的开发落地门槛。</p><p>Ascend C提供三层梯度化可编程接口，全层级均支持完整AI Core算力调度，各层级能力递进、场景适配清晰，具体差异如下：</p><table tabindex="0"><thead><tr><th>API 层级</th><th>语言</th><th>特点</th><th>主要用途</th></tr></thead><tbody><tr><td><strong>TPipe/TQue框架编程 API</strong></td><td><strong>C++</strong></td><td>基于<strong>Tensor</strong>编程，通过<strong>TPipe/TQue</strong>自动管理内存搬运与同步，屏蔽底层细节。</td><td>使用框架自动编排数据搬运和计算，提升编程易用性与开发效率。</td></tr><tr><td><strong>基础 API</strong></td><td><strong>C++</strong></td><td>基于<strong>Tensor</strong>编程，提供<strong>C++ 完备编程能力</strong>，通过<code>LocalMemoryAllocator</code>等分配Tensor，由开发者自主管理同步。</td><td>自主管理同步与内存布局，适配C++ Tensor开发习惯，开放全部底层硬件能力，支撑精细化调优与极致性能实现。</td></tr><tr><td><strong>语言扩展层 SIMD API</strong></td><td><strong>C</strong></td><td>基于<strong>指针</strong>编程，提供<strong>C 完备编程能力</strong>，通过声明静态数组管理本地内存，由开发者自主管理同步。</td><td>自主管理同步与内存，适配C语言开发习惯，开放全部底层硬件能力，支撑精细化调优与极致性能实现。</td></tr></tbody></table><p>开发者可结合自身编程习惯、项目开发效率诉求与性能优化场景，灵活选用对应层级接口完成算子开发。</p><blockquote><p>📌 <strong>提示</strong> Ascend C采用GlobalTensor、LocalTensor分别抽象全局内存与片上本地内存对应的Tensor/Tile。当前版本的LocalTensor不携带Layout内存布局信息，后续版本Tensor API中LocalTensor将原生支持Layout布局管理，具体发布节奏请参考<a href="https://gitcode.com/cann/asc-devkit" target="_blank" rel="noreferrer">Ascend C DevKit仓</a>。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本章系统梳理了AI Core算子从任务分发、硬件调度到代码落地的全链路技术体系：计算任务依托SPMD+SIMD异构并行范式分发至多AI Core并行执行，再根据算子计算特性精准调度至Cube矩阵单元或Vector向量单元完成运算；开发者可结合自身编程习惯与业务场景，灵活选用多级C/C++编程接口，完成算子Kernel的完整逻辑开发。</p><p>后续章节将逐层深入、循序渐进地详解硬件架构原理、Kernel核函数定义、各级编程接口规范、内存管理机制、数据同步逻辑、实战开发流程与性能调优技巧，帮助开发者快速理解核心技术，熟练掌握高性能、高可用的AI Core算子开发能力。</p>',44)])])}const p=t(n,[["render",s]]);export{C as __pageData,p as default};
